INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(49982, 'frFR', 'Témoin de la blessure', 'Parlez à Grol Lame-de-Guerre en Silithus.', 'Le cartel Baille-Fonds a déjà commencé les travaux d’excavation en Silithus pour extraire cette mystérieuse substance.\n\nLe chef de guerre a été très clair : c’est à vous de superviser personnellement les manœuvres d’extraction en Silithus et d’empêcher l’Alliance d’interférer.\n\nGallywix n’a pas eu l’air enchanté de votre nomination, mais personne ne tient tête à Sylvanas…\n\nVous devez vous rendre en Silithus immédiatement. Le commandant de la base attend votre arrivée.', '', '', '', '', '', '', 25996),
(49981, 'frFR', 'Témoin de la blessure', 'Retrouvez le Commandant du SI:7 en Silithus.', 'J’ai déjà envoyé des agents en Silithus pour y établir un camp de base.\n\nLeurs ordres sont d’observer les agissements de la Horde et de documenter toute information qu’ils pourraient trouver au sujet de cette mystérieuse substance.\n\nL’un de mes commandants du SI:7 attend votre arrivée en ce moment même. Hâtez-vous.', '', '', '', '', '', '', 25996),
(49977, 'frFR', 'Convocation à Orgrimmar', 'Parlez à Nathanos le Flétrisseur.', 'Le chef de guerre a demandé que vous reveniez à Orgrimmar dès que possible. Il y a un problème urgent qui requiert votre attention.\n\nJe vous ferai part des détails dès votre arrivée.\n\nVous me trouverez non loin de l’entrée de Fort Grommash. La Dame noire a des projets pour vous, $n. Personnellement, je ne la ferais pas attendre…', '', '', '', '', '', '', 25996),
(49976, 'frFR', 'Dons des déchus', 'Parlez à Mathias Shaw.', 'Plus tôt dans la journée, le roi Wrynn s’est rendu au Repos du lion pour annoncer officiellement la fin de la guerre.\n\nUne fois la foule dissipée, je me suis joint au roi et à ses conseillers à titre privé pour discuter de la mystérieuse substance découverte en Silithus.\n\nCe minerai éclatant serait d’une grande puissance. Et la Horde n’a naturellement pas perdu de temps pour en extraire de la Plaie.\n\nLe roi m’a ordonné de vous tenir au courant des détails, en vue d’une mission de la plus haute importance.', '', '', '', '', '', '', 25996),
(49973, 'frFR', 'Le domaine de Thalyssra', 'Retrouvez Dame Liadrin au Domaine de la Première arcaniste, à Suramar.', 'Le seigneur régent Theron a invité les Sacrenuit à le rejoindre à Lune-d’Argent.\n\nTout d’abord, nous devons leur faire part de l’invitation. Et je préfère traiter ce genre d’affaires en personne.\n\nJe vous demande de m’accompagner à Suramar et d’y rencontrer dame Thalyssra.', '', '', '', '', '', '', 25996),
(49933, 'frFR', 'Pour la Horde', 'Allez voir l’ambassadeur Gardenoire à l’ambassade, à Orgrimmar.', 'Après des millénaires d’isolement, nous sommes de nouveau prêts à faire partie d’un tout supérieur. Notre alliance avec la Horde nous offre cette possibilité, c’est une chance unique qui ne doit pas être gâchée.\n\nL’ambassadeur du chef de guerre vous attend à Orgrimmar, $n. C’est là que vous entamerez votre voyage sur Azeroth. Défendez cette terre et prouvez que les Shal’dorei y ont leur place.\n\nMontrez au monde qui nous sommes, $c. Faites honneur à la Horde, car c’est tout Suramar que vous glorifierez.', '', '', '', '', '', 'Allez voir l’ambassadeur Gardenoire à l’ambassade, à Orgrimmar.', 25996),
(49931, 'frFR', 'Le courroux du titan', '', '', '', '', '', '', '', '', 25996),
(49930, 'frFR', 'L’appel aux alliés', 'Retrouvez le Chef de guerre Sylvanas Coursevent à l’Ambassade, à Orgrimmar.', 'L’altruisme dont a fait preuve le commandement de la Horde pendant la guerre contre la Légion a affaibli nos rangs. Nos ennemis se réjouissent à l’idée de voler ce qui nous appartient. Nous ne les laisserons pas faire.\n\nJ’ai autorisé la construction d’une ambassade à Orgrimmar. Grâce à elle, nous gagnerons d’autres appuis à notre cause. Rejoignez-moi là-bas immédiatement.', '', '', '', '', '', '', 25996),
(49929, 'frFR', 'L’appel aux alliés', 'Retrouvez le Roi Wrynn à l’Ambassade, à Hurlevent.', 'La Horde ne reculera devant rien pour accaparer le sang d’Azeroth. Mais je crains que la guerre contre la Légion ait trop affaibli nos rangs pour que nous puissions parer leurs attaques.\n\nIl est temps pour l’Alliance de rallier de nouveaux membres à sa cause. Nous avons établi une ambassade à Hurlevent pour conduire ces efforts. Retrouvez-moi là-bas.', '', '', '', '', '', '', 25996),
(49928, 'frFR', 'Héritage du Vide', 'Retrouvez Alleria Coursevent à la Faille de Telogrus.', 'Au cours de vos périples sur Azeroth, vous avez appris à maîtriser ces forces qui ne vous laissent aucun répit.\n\nVous êtes désormais une arme redoutable au service de l’Alliance, $p. Regagnez la faille du Vide et nous célébrerons votre réussite comme il se doit.', '', '', '', '', '', '', 25996),
(49866, 'frFR', 'Direction la Pandarie !', 'Présentez-vous à Rell Ventenuit à Hurlevent.', 'Rendez-vous immédiatement au donjon de Hurlevent où le roi Varian Wrynn vous fait mander.$b$bNous avons eu vent d’un conflit dans les mers du sud et avons besoin $gd’un:d’une:c; $c de votre trempe pour en savoir plus.', '', '', '', '', '', '', 25996),
(49865, 'frFR', 'Sauveteur du Cataclysme', 'Présentez-vous à Naraat le Parleterre à Hurlevent.', 'Aile de mort, l’Aspect de la mort draconique, a envoyé ses serviteurs écumer Azeroth à la recherche de toute forme de vie.$b$bNaraat le Parleterre pourra vous en dire plus sur le mont Hyjal, Vashj’ir et les autres zones ciblées par Aile de mort.', '', '', '', '', '', '', 25996),
(49864, 'frFR', 'Guerres sur deux fronts', 'Utilisez les missions spéciales pour choisir votre prochaine destination.', '$n ! L’Alliance entend faire une nouvelle fois appel à vous pour une mission de la plus haute importance.\n\nParticiperez-vous aux efforts de guerre contre Aile de mort et le Marteau du crépuscule ?\n\nOu volerez-vous vers le sud jusqu’en Pandarie, afin de vous emparer des ressources de ce territoire avant la Horde ?\n\nFaites votre choix et joignez-vous au combat !', '', '', '', '', '', '', 25996),
(49863, 'frFR', 'Direction le Norfendre !', 'Faites voile pour le Norfendre.$b$bMontez à bord du navire amarré au Port de Hurlevent et en partance pour la Toundra Boréenne, ou embarquez sur celui des Paluns qui se rend au Fjord Hurlant.', 'Le roi-liche s’agite au nord.$b$bSon armée de morts-vivants marche sur le Norfendre, ne laissant que mort et destruction dans son sillage.$b$bVous devez les arrêter, $n.', '', '', '', '', '', '', 25996),
(49862, 'frFR', 'Direction l’Outreterre !', 'Franchissez la Porte des ténèbres dans les Terres Foudroyées.', 'La Légion ardente, une armée composée d’innombrables démons, a attaqué l’Outreterre, le monde natal dévasté des Draeneï. Nous avons besoin des aventuriers de l’Alliance pour empêcher l’annihilation totale de l’Outreterre par l’envahisseur.$b$bRendez-vous dans les terres Foudroyées et franchissez la Porte des ténèbres.', '', '', '', '', '', '', 25996),
(49860, 'frFR', 'L’appel de l’aventure', 'Utilisez les missions spéciales pour choisir votre prochaine destination.', 'Les récits de votre héroïsme ont gagné les confins d’Azeroth… et au-delà. Vos talents sont sollicités ailleurs.\n\nAllez-vous franchir la Porte des ténèbres pour combattre la Légion ardente sur le monde dévasté d’Outreterre ?\n\nOu voler vers le nord pour rejoindre l’armée qui affronte le roi-liche en Norfendre ?\n\nLe choix vous appartient, $gaventurier:aventurière;.', '', '', '', '', '', '', 25996),
(49855, 'frFR', 'Catastrophe au mont Hyjal', 'Parlez à l’Émissaire cénarien Sabot-Noir pour obtenir un moyen de transport pour Reflet-de-Lune.', 'Nos frères du Cercle cénarien nous signalent que les serviteurs d’Aile de mort ont lancé une offensive destructrice sur l’Arbre-Monde et menacent de le réduire en cendres !$B$BAdressez-vous à l’émissaire cénarien Sabot-Noir afin d’accéder à Reflet-de-Lune. Vous le trouverez dans le quartier tauren de la vallée de la Sagesse, à Orgrimmar.', 'Passage vers Reflet-de-Lune obtenu', '', '', '', '', 'Parlez à l’Émissaire Chant-du-vent à Havrenuit, à Reflet-de-Lune.', 25996),
(49852, 'frFR', 'Direction la Pandarie !', 'Présentez-vous au Fort Grommash à Orgrimmar.', 'Vous êtes $gsommé:sommée; de vous présenter sur-le-champ au fort Grommash.$b$bOn nous a rapporté l’existence d’un nouveau continent au sud. Nous comptons vous y envoyer, $gaccompagné:accompagnée; d’un petit contingent de soldats, afin de revendiquer le territoire et ses ressources pour la Horde.', '', '', '', '', '', '', 25996),
(49851, 'frFR', 'Sauveteur du Cataclysme', 'Présentez-vous au Long-voyant Krogar à Orgrimmar.', 'Aile de mort, l’Aspect de la mort draconique, a envoyé ses serviteurs écumer Azeroth à la recherche de toute forme de vie.$b$b Le long-voyant Krogar d’Orgrimmar pourra vous en dire plus sur le mont Hyjal, Vashj’ir et les autres zones ciblées par Aile de mort.', '', '', '', '', '', '', 25996),
(49846, 'frFR', 'Guerres sur deux fronts', 'Utilisez les missions spéciales pour choisir votre prochaine destination.', '$n ! La Horde entend faire une nouvelle fois appel à vous pour une mission de la plus haute importance.\n\nParticiperez-vous aux efforts de guerre contre Aile de mort et le Marteau du crépuscule ?\n\nOu volerez-vous vers le sud jusqu’en Pandarie, afin de vous emparer des ressources de ce territoire avant l’Alliance ?\n\nFaites votre choix et joignez-vous au combat !', '', '', '', '', '', '', 25996),
(49817, 'frFR', 'Direction le Norfendre !', 'Prenez un zeppelin pour le Norfendre.$b$bMontez à bord de celui amarré dans les Clairières de Tirisfal en partance pour le Fjord Hurlant, ou embarquez sur celui d’Orgrimmar en partance pour la Toundra Boréenne.', 'Le roi-liche s’agite au nord.$b$bSon armée de morts-vivants marche sur le Norfendre, ne laissant que mort et destruction dans son sillage.$b$bVous devez les arrêter, $n.', '', '', '', '', '', '', 25996),
(49816, 'frFR', 'Direction l’Outreterre !', 'Franchissez la Porte des ténèbres dans les Terres Foudroyées.', 'La Légion ardente, une armée composée d’innombrables démons, a attaqué l’Outreterre, le monde natal dévasté des Orcs. Nous avons besoin des aventuriers de la Horde pour empêcher l’annihilation totale de l’Outreterre par l’envahisseur.$b$bRendez-vous dans les terres Foudroyées et franchissez la Porte des ténèbres.', '', '', '', '', '', '', 25996),
(49813, 'frFR', 'L’appel de l’aventure', 'Utilisez les missions spéciales pour choisir votre prochaine destination.', 'Les récits de votre héroïsme ont gagné les confins d’Azeroth… et au-delà. Vos talents sont sollicités ailleurs.\n\nAllez-vous franchir la Porte des ténèbres pour combattre la Légion ardente sur le monde dévasté d’Outreterre ?\n\nOu voler vers le nord pour rejoindre l’armée qui affronte le roi-liche en Norfendre ?\n\nLe choix vous appartient, $gaventurier:aventurière;.', '', '', '', '', '', '', 25996),
(49812, 'frFR', 'Délas à Dalaran', 'Trouvez Délas Croc-de-Lune au Monument à Antonidas, à Dalaran.', 'Délas Croc-de-Lune a besoin de notre aide. En échange, elle nous aidera à déchiffrer le codex de commandement.$B$BTrouvez-la au plus vite, je vous en prie. Elle se recueille souvent au monument dédié à la mémoire d’Antonidas, le grand héros du Kirin Tor.', '', '', '', '', '', 'Trouvez Délas Croc-de-Lune au Monument à Antonidas, à Dalaran.', 25996),
(49789, 'frFR', 'Le serment', 'Retournez à Hurlevent et parlez à Anduin.', 'Les Éthériens attendaient patiemment que quelqu’un ayant étudié la puissance du Vide soit corrompu par l’influence des Dieux très anciens.\n\nNous sommes arrivés à temps pour les sauver, et je les aiderai à apprendre à résister aux murmures.\n\nUmbric est prêt à rejoindre l’Alliance. Retournons à Hurlevent en informer le roi Wrynn.', '', '', '', '', '', '', 25996),
(49788, 'frFR', 'Pour l’Alliance', 'Allez voir l’ambassadeur Mauregarde à l’ambassade, à Hurlevent.', 'Contrôler les murmures requiert discipline et une concentration de tous les instants. Votre dévouement est une véritable source d’inspiration pour les Ren’dorei… car nous sommes les enfants du Vide.\n\nVous avez appris de nombreuses leçons, ici, mais il est temps pour vous de vous aventurer au-delà de la faille de Telogrus.\n\nRendez-vous à Hurlevent, le cœur de l’Alliance. L’ambassadeur du roi vous y accueillera et vous guidera tout au long de votre périple.\n\nAzeroth doit être défendue. Personne n’est plus à même de répondre à cet appel que vous, $p.', '', '', '', '', '', 'Allez voir l’ambassadeur Mauregarde à l’ambassade, à Hurlevent.', 25996),
(49787, 'frFR', 'Les terres Fantômes', 'Trouvez la demeure d’Umbric dans les Terres Fantômes.', 'Un Elfe de sang du nom d’Umbric et ses serviteurs ont été chassés de Lune-d’Argent pour avoir étudié la magie du Vide.\n\nBien que cette pratique soit interdite, c’est une sentence extrême.\n\nCependant, cela ouvre des possibilités pour l’Alliance. Si nous parvenons à trouver ces parias, nous pourrons peut-être les rallier à notre cause et, bien plus important, les aider à comprendre le Vide avant qu’il les corrompe.', '', '', '', '', '', '', 25996),
(49784, 'frFR', 'Héritage des Sacrenuit', 'Allez voir la Première arcaniste Thalyssra au Palais Sacrenuit.', 'Vous faites partie des premiers Shal’dorei à avoir exploré les étendues d’Azeroth. Il est temps pour vous de rentrer à la maison.\n\nRevenez à Suramar. Grâce à vous, notre peuple a retrouvé sa place dans ce monde, et nous tenons à vous remercier.', '', '', '', '', '', '', 25996),
(49783, 'frFR', 'L’héritage de Haut-Roc', 'Retrouvez Mayla Haut-Roc à Totem-du-Tonnerre.', 'Vous avez fait un long séjour en Azeroth, $p. Et au cours de celui-ci, vous avez porté haut les couleurs de Haut-Roc.\n\nTotem-du-Tonnerre vous invite à présent à revenir. Il est temps que l’on vous remercie pour tout ce que vous avez accompli.', '', '', '', '', '', '', 25996),
(49782, 'frFR', 'Héritage des Sancteforge', 'Allez voir le Capitaine Fareeya sur le Vindicaar.', 'Vous avez fait preuve d’une grande dévotion à l’Alliance, $p. Je n’aurais fait mieux moi-même. Enfin si… mais de peu.\n\nRejoignez-moi à bord du Vindicaar. Vos efforts assidus méritent récompense.', '', '', '', '', '', '', 25996),
(49773, 'frFR', 'Pour la Horde', 'Allez voir l’ambassadeur Gardenoire à l’ambassade, à Orgrimmar.', 'Une nouvelle ère s’ouvre pour Haut-Roc, $n.\n\nAprès des siècles d’isolement, les liens avec nos cousins de Kalimdor se sont resserrés. Notre combat pour sauver notre terre nous a permis de nouer de solides amitiés avec les peuples de la Horde. \n\nAfin de montrer à nos nouveaux alliés la puissance dont nous sommes capables, de braves Taurens comme vous se doivent de répondre à l’appel de l’aventure.\n\nVous avez reçu une invitation en provenance d’Orgrimmar. Retrouvez-y l’ambassadeur à l’ambassade du chef de guerre, puis entamez votre périple en Azeroth. \n\nQue la Terre-Mère soit avec vous, $n.', '', '', '', '', '', 'Allez voir l’ambassadeur Gardenoire à l’ambassade, à Orgrimmar.', 25996),
(49772, 'frFR', 'Pour l’Alliance', 'Allez voir l’ambassadeur Mauregarde à l’ambassade, à Hurlevent.', 'L’armée de la Lumière a été fondée dans un seul et unique but : vaincre la Légion. Mais bien que cet objectif soit aujourd’hui atteint, le devoir nous appelle de nouveau.\n\nAzeroth est un monde assailli d’ennemis. Utilisez votre savoir pour vaincre les ténèbres et faire respecter les idéaux de l’Alliance.\n\nAllez à Hurlevent, trouvez l’ambassadeur du roi à l’ambassade, puis apportez la justice de la Lumière à tous.\n\nPheta thones gamera, $n.', '', '', '', '', '', 'Allez voir l’ambassadeur Mauregarde à l’ambassade, à Hurlevent.', 25996),
(49756, 'frFR', 'Forces ténébreuses', 'Éliminez Qy’telek, héraut d’Uul’gyneth.', 'Les Dieux très anciens ont déchaîné l’un de leurs sans-visage sur les Pitons-du-Tonnerre. Ce monstre est en train de profaner le foyer de mes semblables !\n\nNous devons unir nos forces pour débarrasser cet endroit d’une telle ignominie.\n\nJ’ose espérer que la destruction de ce héraut fera fuir nos ennemis de Mulgore. Que nos armes frappent juste, $n !', '', 'Héraut d’Uul’gyneth', 'Qy’telek', '', '', '', 25996),
(49698, 'frFR', 'Les Sancteforge', 'Accompagnez Turalyon jusqu’au Vindicaar.', '$n, vous avez vu de vos yeux ce dont mes frères sont capables. Depuis des millénaires, nous sommes forgés spécialement pour combattre la Légion.\n\nAujourd’hui, je crois qu’il est temps de prendre les armes aux côtés de nos frères et sœurs de l’Alliance.\n\nRejoignez-nous au Vindicaar. Je pense que nous avons bien des choses à discuter avec le capitaine Fareeya.', '', '', '', '', '', 'Allez voir le capitaine Fareeya sur le Vindicaar.', 25996),
(49614, 'frFR', 'Les Sacrenuit', 'Retournez voir le Chef de guerre à Orgrimmar.', 'Le chef de guerre en sera ravi.\n\nThalyssra et ses Sacrenuit feront des alliés de poids, à n’en point douter.', '', '', '', '', '', '', 25996),
(49613, 'frFR', 'Lune-d’Argent', 'Rejoignez Dame Liadrin à Lune-d’Argent.', 'Les Sacrenuit ont vécu isolés des millénaires durant. Mais ils se sont à nouveau dévoilés au monde et c’est à nous de les guider sur le droit chemin.\n\nLe seigneur régent Theron les a conviés à Lune-d’Argent.\n\nVenez, $n, rendons-nous à Lune-d’Argent avec Thalyssra.', '', '', '', '', '', '', 25996),
(49567, 'frFR', 'L’appel du héros : Nagrand !', 'Parlez au Lieutenant Balfor en Nagrand, sur Draenor.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter au lieutenant Balfor en Nagrand, sur Draenor.\n\nYrel a convaincu l’Alliance d’y établir un avant-poste dans le cadre de notre lutte contre le clan Chanteguerre.\n\nRalliez Nagrand par la voie des airs et rejoignez Balfor et la caravane de ravitaillement.\n\nGloire à l’Alliance !', '', '', '', '', '', 'Parlez au Lieutenant Balfor en Nagrand, sur Draenor.', 25996),
(49566, 'frFR', 'L’appel du héros : les flèches d’Arak !', 'Parlez à Azik dans les Flèches d’Arak.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter à Azik, dans les flèches d’Arak.\n\nDes arakkoa dépourvus d’ailes ont été aperçus fuyant les flèches d’Arak. À en croire la rumeur, c’est une super-arme de la Horde de Fer qui provoquerait cette panique.\n\nNous devons découvrir les raisons précises de leur exil, ainsi que la cause de cette étrange atrophie de leurs ailes.\n\nGloire à l’Alliance !', '', '', '', '', '', 'Parlez à Azik dans les Flèches d’Arak.', 25996),
(49565, 'frFR', 'L’appel du héros : Talador !', 'Parlez au Contremaître Eksos en Talador.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter au contremaître Eksos, en Talador.\n\nLa Horde de Fer a jeté son dévolu sur cette région idéalement située pour envoyer rapidement et facilement des renforts aux quatre coins de Draenor.\n\nAussi le contremaître Eksos a-t-il été chargé d’y établir un avant-poste. Rendez-vous sur place et arrêtez la Horde de Fer.\n\nGloire à l’Alliance !', '', '', '', '', '', 'Parlez au Contremaître Eksos en Talador.', 25996),
(49564, 'frFR', 'L’appel du héros : Gorgrond !', 'Parlez à Yrel en Gorgrond.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter à Yrel, en Gorgrond.\n\nElle organise une expédition à destination des terres sauvages de la région avec le concours de Maraad.\n\nEn explorant ces terres plus avant, nous espérons trouver un moyen d’exploiter les faiblesses de la Horde de Fer.\n\nAidez-les dans leur entreprise.\n\nGloire à l’Alliance !', '', '', '', '', '', 'Parlez à Yrel en Gorgrond.', 25996),
(49562, 'frFR', 'L’appel du héros : la vallée d’Ombrelune !', 'Parlez au Prophète Velen dans la Vallée d’Ombrelune, sur Draenor.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter au prophète Velen dans la vallée d’Ombrelune, sur Draenor.\n\nLa destruction de la Porte des ténèbres a empêché la Horde de Fer d’envahir Azeroth, mais ces vauriens n’ont pas dit leur dernier mot.\n\nAvec la bénédiction de Velen, nous allons établir une base stratégique sur Draenor pour lutter contre les ennemis de notre monde.\n\nGloire à l’Alliance !', '', '', '', '', '', 'Parlez au Prophète Velen dans la Vallée d’Ombrelune, sur Draenor.', 25996),
(49561, 'frFR', 'L’appel du héros : les terres de l’Angoisse !', 'Parlez au Maître-archer Li sur l’Échine du Serpent.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter au maître-archer Li à l’Échine du Serpent, dans le val de l’Éternel printemps.\n\nLes Pandashan sont aux prises avec une armée de mantides qui menace d’envahir l’ensemble de la Pandarie.\n\nVous pouvez vous rendre sur place par la voie des airs à l’aide d’un cerf-volant.\n\nGloire à l’Alliance !', '', '', '', '', '', 'Parlez au Maître-archer Li sur l’Échine du Serpent.', 25996),
(49560, 'frFR', 'L’appel du héros : les steppes de Tanglong !', 'Parlez à Taran Zhu dans les Steppes de Tanglong.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter à Taran Zhu, dans les steppes de Tanglong.\n\nLes Pandashan veulent à tout prix reconquérir leurs terres tombées aux mains des yaungols, mais leurs effectifs sont insuffisants.\n\nAidez-les à chasser l’envahisseur !\n\nGloire à l’Alliance !', '', '', '', '', '', 'Parlez à Taran Zhu dans les Steppes de Tanglong.', 25996),
(49559, 'frFR', 'L’appel du héros : le sommet de Kun-Lai !', 'Parlez au Messager grumelot dans la Vallée des Quatre vents.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de prêter main-forte au chroniqueur Cho, au sommet de Kun-Lai.\n\nAdressez-vous à un messager grumelot dans la vallée des Quatre vents, et il vous indiquera le chemin.\n\nGloire à l’Alliance !', '', '', '', '', '', 'Parlez au Messager grumelot dans la Vallée des Quatre vents.', 25996),
(49558, 'frFR', 'L’appel du héros : les étendues sauvages de Krasarang !', 'Parlez à Ken-Ken dans les Étendues sauvages de Krasarang.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter au guet de Zhu, dans les étendues sauvages de Krasarang.\n\nLe bruit court que les Pandarens de la région sont plongés dans une étrange léthargie.\n\nAllez voir Ken-Ken, au guet de Zhu. Il pourra peut-être vous en dire plus sur cet étrange phénomène.', '', '', '', '', '', 'Parlez à Ken-Ken dans les Étendues sauvages de Krasarang.', 25996),
(49557, 'frFR', 'L’appel du héros : la vallée des Quatre vents !', 'Parlez à Chen Brune d’Orage dans la Vallée des Quatre vents.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter à Chen Brune d’Orage, dans la vallée des Quatre vents.\n\nLes Brune d’Orage sont réputés pour leur audace, et l’Alliance gagnerait à s’en inspirer.\n\nPartez à l’aventure avec eux et découvrez les secrets de la Pandarie.\n\nGloire à l’Alliance !', '', '', '', '', '', 'Parlez à Chen Brune d’Orage dans la Vallée des Quatre vents.', 25996),
(49556, 'frFR', 'L’appel du héros : la forêt de Jade !', 'Allez voir le Grand amiral Jes-Tereth au Donjon de Hurlevent.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter au donjon de Hurlevent.\n\nLe grand amiral Jes-Tereth rassemble une équipe en vue d’une mission de la plus haute importance.\n\nRendez-vous à Hurlevent séance tenante pour recevoir vos instructions.\n\nGloire à l’Alliance !', '', '', '', '', '', '', 25996),
(49555, 'frFR', 'L’appel du héros : la Couronne de glace !', 'Parlez à l’Officier Van Rossem à Dalaran, au-dessus de la Forêt du Chant de cristal.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter à l’officier Van Rossem à Dalaran, au-dessus de la forêt du Chant de cristal.\n\nL’expédition de la Bravoure a besoin d’aventuriers supplémentaires pour participer au siège de la citadelle de la Couronne de glace où Arthas s’est retranché.\n\nL’heure du châtiment a sonné pour le roi-liche.\n\nGloire à l’Alliance !', '', '', '', '', '', 'Parlez à l’Officier Van Rossem à Dalaran, au-dessus de la Forêt du Chant de cristal.', 25996),
(49554, 'frFR', 'L’appel du héros : les pics Foudroyés !', 'Parlez à Rin Duoctane à Dalaran, au-dessus de la Forêt du Chant de cristal.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter à Rin Duoctane à Dalaran, au-dessus de la forêt du Chant de cristal.\n\nLes gobelins de K3 ont fondé une ville dans les pics Foudroyés et ils nous envoient leur ambassadeur pour recruter des aventuriers.\n\nAllez voir Rin et voyez comment pourvoir aux besoins des habitants de K3. Ils constitueraient de précieux alliés dans notre lutte contre le roi-liche.\n\nGloire à l’Alliance !', '', '', '', '', '', 'Parlez à Rin Duoctane à Dalaran, au-dessus de la Forêt du Chant de cristal.', 25996),
(49553, 'frFR', 'L’appel du héros : le bassin de Sholazar !', 'Parlez à l’Archimage Pentarus à Dalaran, au-dessus de la Forêt du Chant de cristal.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter à l’archimage Pentarus à Dalaran, au-dessus de la forêt du Chant de cristal.\n\nParti explorer le bassin de Sholazar, Hemet Nesingwary a disparu avec l’ensemble de son expédition.\n\nNous en savons très peu sur cette contrée luxuriante, mais elle abrite peut-être des secrets susceptibles de nous aider dans notre lutte contre le roi-liche.\n\nGloire à l’Alliance !', '', '', '', '', '', 'Parlez à l’Archimage Pentarus à Dalaran, au-dessus de la Forêt du Chant de cristal.', 25996),
(49552, 'frFR', 'L’appel du héros : Zul’Drak !', 'Parlez au Seigneur croisé Lantinga à Zul’Drak.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter au seigneur croisé Lantinga, à Zul’Drak.\n\nLe Fléau massacre la population locale avant d’incorporer ses victimes dans son armée.\n\nAidez la Croisade d’argent et la Lame d’ébène à neutraliser cette terrible menace.\n\nGloire à l’Alliance !', '', '', '', '', '', 'Parlez au Seigneur croisé Lantinga à Zul’Drak.', 25996),
(49551, 'frFR', 'L’appel du héros : le fjord Hurlant !', 'Parlez à Macalroy au Fjord Hurlant.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter à Macalroy, au fjord Hurlant.\n\nSituée au cœur de la région, la cité portuaire de Valgarde occupe une position clé pour attaquer le Fléau.\n\nAidez les soldats stationnés sur place.\n\nGloire à l’Alliance !', '', '', '', '', '', 'Parlez à Macalroy au Fjord Hurlant.', 25996),
(49550, 'frFR', 'L’appel du héros : la vallée d’Ombrelune !', 'Parlez au Chef d’escadrille Nuainn dans la Vallée d’Ombrelune, en Outreterre.', 'Tous les citoyens de l’Alliance en état de porter les armes sont sommés de se présenter au chef d’escadrille Nuainn dans la vallée d’Ombrelune, en Outreterre.\n\nLa Légion ardente assiège le bastion des Marteaux-Hardis et les nôtres sont en danger de mort.\n\nNous devons soutenir le bastion et mettre un terme aux assauts incessants de ces démons !\n\nGloire à l’Alliance !', '', '', '', '', '', 'Parlez au Chef d’escadrille Nuainn dans la Vallée d’Ombrelune, en Outreterre.', 25996),
(49549, 'frFR', 'Ordre du chef de guerre : Nagrand !', 'Parlez au Garde de pierre Brox en Nagrand, sur Draenor.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter au garde de pierre Brox, en Nagrand, sur Draenor.\n\nThrall est en train d’établir un avant-poste de la Horde et a besoin d’aide pour repousser le clan Chanteguerre.\n\nParlez à Bron Corne-Céleste afin de vous envoler pour Nagrand et rejoignez la caravane de ravitaillement.\n\nPour la Horde !', '', '', '', '', '', 'Parlez au Garde de pierre Brox en Nagrand, sur Draenor.', 25996),
(49548, 'frFR', 'Ordre du chef de guerre : les flèches d’Arak !', 'Parlez à Azik dans les Flèches d’Arak.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter à Azik, dans les flèches d’Arak.\n\nDes arakkoa dépourvus d’ailes ont été aperçus fuyant les flèches d’Arak. À en croire la rumeur, c’est une super-arme de la Horde de Fer qui provoquerait cette panique.\n\nNous devons découvrir les raisons précises de leur exil, ainsi que la cause de cette étrange atrophie de leurs ailes.\n\nPour la Horde !', '', '', '', '', '', 'Parlez à Azik dans les Flèches d’Arak.', 25996),
(49547, 'frFR', 'Ordre du chef de guerre : Talador !', 'Parlez au Contremaître Grobash en Talador.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter au contremaître Grobash, en Talador.\n\nLa Horde de Fer a jeté son dévolu sur cette région idéalement située pour envoyer rapidement et facilement des renforts aux quatre coins de Draenor.\n\nAussi le contremaître Grobash a-t-il été chargé d’y établir un avant-poste. Rendez-vous sur place et arrêtez la Horde de Fer.\n\nPour la Horde !', '', '', '', '', '', 'Parlez au Contremaître Grobash en Talador.', 25996),
(49546, 'frFR', 'Ordre du chef de guerre : Gorgrond !', 'Parlez à Durotan en Gorgrond.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter à Durotan, en Gorgrond.\n\nDurotan est à la recherche d’alliés capables de nous aider à explorer les terres sauvages de Gorgrond. Ce faisant, il espère y découvrir d’anciens pouvoirs à même d’anéantir la Horde de Fer.\n\nAllez lui parler et percez les mystères de cette contrée tourmentée.\n\nPour la Horde !', '', '', '', '', '', 'Parlez à Durotan en Gorgrond.', 25996),
(49545, 'frFR', 'Ordre du chef de guerre : la crête de Givrefeu !', 'Parlez au Long-voyant Drek’Thar sur la Crête de Givrefeu.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter au long-voyant Drek’Thar, sur la crête de Givrefeu.\n\nLa destruction de la Porte des ténèbres a empêché la Horde de Fer d’envahir Azeroth, mais ces vauriens n’ont pas dit leur dernier mot.\n\nForts de l’aide du long-voyant Drek’Thar, nous allons être en mesure d’établir une tête de pont stratégique sur Draenor, afin de contrer nos ennemis.\n\nPour la Horde !', '', '', '', '', '', 'Parlez au Long-voyant Drek’Thar sur la Crête de Givrefeu.', 25996),
(49543, 'frFR', 'Ordre du chef de guerre : les terres de l’Angoisse !', 'Parlez au Maître-archer Li sur l’Échine du Serpent.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter au maître-archer Li, sur l’Échine du Serpent, dans le val de l’Éternel printemps.\n\nLes Pandashan sont aux prises avec une armée de mantides qui menace d’envahir l’ensemble de la Pandarie.\n\nVous pouvez vous rendre sur place par la voie des airs à l’aide d’un cerf-volant.\n\nLe destin vous appelle !', '', '', '', '', '', 'Parlez au Maître-archer Li sur l’Échine du Serpent.', 25996),
(49542, 'frFR', 'Ordre du chef de guerre : les steppes de Tanglong !', 'Parlez à Taran Zhu dans les Steppes de Tanglong.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter à Taran Zhu, dans les steppes de Tanglong.\n\nLes Pandashan veulent à tout prix reconquérir leurs terres tombées aux mains des yaungols, mais leurs effectifs sont insuffisants.\n\nAidez-les à chasser l’envahisseur !\n\nPour la Horde !', '', '', '', '', '', 'Parlez à Taran Zhu dans les Steppes de Tanglong.', 25996),
(49541, 'frFR', 'Ordre du chef de guerre : le sommet de Kun-Lai !', 'Parlez au Messager grumelot dans la Vallée des Quatre vents.', 'Tous les membres de la Horde en état de porter les armes sont sommés d’aider le chroniqueur Cho, au sommet de Kun-Lai.\n\nAdressez-vous à un messager grumelot dans la vallée des Quatre vents. Il vous indiquera le chemin.\n\nPour la Horde !', '', '', '', '', '', 'Parlez au Messager grumelot dans la Vallée des Quatre vents.', 25996),
(49540, 'frFR', 'Ordre du chef de guerre : les étendues sauvages de Krasarang !', 'Parlez à Ken-Ken dans les Étendues sauvages de Krasarang.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter au guet de Zhu, dans les étendues sauvages de Krasarang.\n\nLe bruit court que les Pandarens de la région sont plongés dans une étrange léthargie.\n\nAllez voir Ken-Ken, au guet de Zhu. Il pourra peut-être vous en dire plus sur cet étrange phénomène.', '', '', '', '', '', 'Parlez à Ken-Ken dans les Étendues sauvages de Krasarang.', 25996),
(49539, 'frFR', 'Ordre du chef de guerre : la vallée des Quatre vents !', 'Parlez à Chen Brune d’Orage dans la Vallée des Quatre vents.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter à Chen Brune d’Orage, dans la vallée des Quatre vents.\n\nLes Brune d’Orage sont réputés pour leur audace, et la Horde gagnerait à s’en inspirer.\n\nPartez à l’aventure avec eux et découvrez les secrets de la Pandarie.\n\nPour la Horde !', '', '', '', '', '', 'Parlez à Chen Brune d’Orage dans la Vallée des Quatre vents.', 25996),
(49538, 'frFR', 'Ordre du chef de guerre : la forêt de Jade !', 'Parlez au Général Nazgrim au Fort Grommash.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter au général Nazgrim, à Orgrimmar.\n\nNos récentes victoires navales contre l’Alliance n’ont fait que renforcer notre détermination.\n\nGagnez le fort Grommash et mettez-vous au service de la flotte d’invasion de la Horde.\n\nPour la Horde !', '', '', '', '', '', '', 25996),
(49537, 'frFR', 'Ordre du chef de guerre : la Couronne de glace !', 'Parlez au Saccageur-des-cieux Klum à Dalaran, au-dessus de la Forêt du Chant de cristal.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter au saccageur-des-cieux Klum à Dalaran, au-dessus de la forêt du Chant de cristal.\n\nL’Offensive chanteguerre a besoin d’aventuriers supplémentaires pour participer au siège de la citadelle de la Couronne de glace où Arthas s’est retranché.\n\nIl est temps que le roi-liche paie pour ses crimes.\n\nPour la Horde !', '', '', '', '', '', 'Parlez au Saccageur-des-cieux Klum à Dalaran, au-dessus de la Forêt du Chant de cristal.', 25996),
(49536, 'frFR', 'Ordre du chef de guerre : les pics Foudroyés !', 'Parlez à Rin Duoctane à Dalaran, au-dessus de la Forêt du Chant de cristal.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter à Rin Duoctane à Dalaran, au-dessus de la forêt du Chant de cristal.\n\nLes gobelins de K3 ont fondé une ville dans les pics Foudroyés et ils nous envoient leur ambassadeur pour recruter des aventuriers.\n\nAllez voir Rin et voyez comment pourvoir aux besoins des habitants de K3. Ils feraient de précieux alliés dans notre lutte contre le roi-liche.\n\nPour la Horde !', '', '', '', '', '', 'Parlez à Rin Duoctane à Dalaran, au-dessus de la Forêt du Chant de cristal.', 25996),
(49535, 'frFR', 'Ordre du chef de guerre : le bassin de Sholazar !', 'Parlez à l’Archimage Pentarus à Dalaran, au-dessus de la Forêt du Chant de cristal.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter à l’archimage Pentarus à Dalaran, au-dessus de la forêt du Chant de cristal.\n\nParti explorer le bassin de Sholazar, Hemet Nesingwary a disparu avec l’ensemble de son expédition.\n\nNous en savons très peu sur cette contrée luxuriante, mais elle abrite peut-être des secrets susceptibles de nous aider dans notre lutte contre le roi-liche.\n\nPour la Horde !', '', '', '', '', '', 'Parlez à l’Archimage Pentarus à Dalaran, au-dessus de la Forêt du Chant de cristal.', 25996),
(49534, 'frFR', 'Ordre du chef de guerre : Zul’Drak !', 'Parlez au Seigneur croisé Lantinga à Zul’Drak.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter au seigneur croisé Lantinga, à Zul’Drak.\n\nLe Fléau massacre la population locale avant d’incorporer ses victimes dans son armée.\n\nAidez la Croisade d’argent et la Lame d’ébène à neutraliser cette terrible menace.\n\nPour la Horde !', '', '', '', '', '', 'Parlez au Seigneur croisé Lantinga à Zul’Drak.', 25996),
(49533, 'frFR', 'Ordre du chef de guerre : le fjord Hurlant !', 'Parlez à l’Apothicaire Lysander dans le Fjord Hurlant.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter à l’apothicaire Lysander, dans le fjord Hurlant.\n\nLes Réprouvés ont établi une place forte sur le littoral est du Norfendre.\n\nL’heure est venue de frapper le Fléau avec notre formidable puissance militaire et l’arme calamiteuse actuellement développée par la Société royale des apothicaires.\n\nPour la Horde !', '', '', '', '', '', 'Parlez à l’Apothicaire Lysander dans le Fjord Hurlant.', 25996),
(49532, 'frFR', 'Ordre du chef de guerre : la vallée d’Ombrelune !', 'Parlez au Garde de sang Gulmok dans la Vallée d’Ombrelune, en Outreterre.', 'Tous les membres de la Horde en état de porter les armes sont sommés de se présenter au garde de sang Gulmok, dans la vallée d’Ombrelune, en Outreterre.\n\nLa Légion ardente tente d’assiéger le village d’Ombrelune, mais nos troupes d’élite kor’kronnes leur montrent ce qu’il en coûte de se frotter à la Horde.\n\nÉcrasez la Légion.\n\nPour la Horde !', '', '', '', '', '', 'Parlez au Garde de sang Gulmok dans la Vallée d’Ombrelune, en Outreterre.', 25996),
(49474, 'frFR', 'L’éclat maudit', 'Apportez l’Éclat maudit à l’Arcanomancien Vridiel, à Dalaran dans les îles Brisées.', '<Un éclat métallique irisé de reflets chatoyants attire votre regard. À votre contact, l’une de ses extrémités gonfle et se met à fondre. Les gouttes qui tombent au sol émettent un grésillement accompagné d’une odeur âcre et fétide.$b$bUn artisan de Dalaran qui a l’habitude de travailler le métal pourra certainement vous en dire davantage.>', '', '', '', '', '', '', 25996),
(49473, 'frFR', 'Un effort titanesque', 'Apportez $1oa unités d’Essence d’éveil à l’Arcanomancien Vridiel.', 'La réaction s’intensifie de jour en jour. Même si nous gagnons le combat contre la Légion, nous pourrions très bien perdre quelque chose qui nous est cher.\n\nS’agit-il des prémices d’un bouleversement bien plus profond ? Quel sera le destin de notre monde, $n ?\n\nJe tenterai de le découvrir dans ma forge, comme je l’ai toujours fait. Vos réponses, en revanche, vous attendent ailleurs.', '', '', '', '', '', '', 25996),
(49472, 'frFR', 'Un effort titanesque', 'Apportez $1oa unités d’Essence d’éveil à l’Arcanomancien Vridiel.', 'Illidan a peut-être forcé le cours du destin, mais rapprocher Argus et Azeroth n’a fait qu’accélérer la réaction provoquée par l’effondrement du Puits de la nuit.\n\nJe suis persuadé que les manigances de la Légion sur Argus déstabilisent encore davantage les pouvoirs que nous exploitons depuis des années sans connaître les tenants et aboutissants.\n\nBien entendu, il me faut encore étayer cette théorie.', '', '', '', '', '', '', 25996),
(49445, 'frFR', 'Un échange primordial', '', '', '', '', '', '', '', '', 25996),
(49354, 'frFR', 'Le souvenir du Puits de soleil', 'Terminez le scénario « Le souvenir du Puits de soleil ».', 'Le seigneur régent Theron souhaite montrer notre Puits de soleil à la première arcaniste Thalyssra.\n\nJ’ignore s’il autorisera Alleria Coursevent à participer à la rencontre, néanmoins nous sommes invités à les rejoindre.', '', '', '', '', '', '', 25996),
(49293, 'frFR', 'Assaut du site d’invasion', 'Terminez 3 Sites d’invasion standards.', 'Nous ne devons pas céder le moindre monde à la Légion. Poursuivez l’offensive sur le site d’invasion et écrasez la Légion sous votre talon.', '', '', '', '', '', '', 25996),
(49266, 'frFR', 'Forge des Éons', 'Assistez au rituel des Sancteforge.', 'Cela fait bien longtemps que les Sancteforge représentent la flamme de l’espoir face à la Légion.\n\nMais très peu savent vraiment ce qu’on exige de ceux qui sont appelés à incarner le courroux de la Lumière.\n\nCes rares champions élus parmi l’armée de la Lumière sont prêts à subir leur épreuve finale.\n\nNous ferez-vous l’honneur d’assister à ce rituel ?', '', '', '', '', '', '', 25996),
(49224, 'frFR', 'Le creuset de Halo-du-Néant', 'Imprégnez une relique avec Fortification de Halo-du-Néant en utilisant le Creuset de Halo-du-Néant.', 'Le creuset vibre de puissance. Bientôt, nos armes brilleront autant que les étoiles !\n\nNous avons besoin de ce pouvoir si nous voulons avoir une chance de vaincre la Légion ici.\n\n$n, vous avez subi de rudes épreuves pour nous conduire à ce moment. L’honneur d’exploiter la puissance du creuset en premier vous revient de droit.', '', '', '', '', '', '', 25996),
(49196, 'frFR', 'Site d’invasion prioritaire : seigneur des abîmes Vilemus', '', '', '', '', '', '', '', '', 25996),
(49195, 'frFR', 'Site d’invasion prioritaire : Occularus', '', '', '', '', '', '', '', '', 25996),
(49143, 'frFR', 'L’essence de la mère de la Lumière', 'Récupérez $1oa Vestiges de la Lumière.', 'L’heure est grave, $n. Notre campagne ne doit à aucun prix s’essouffler.\n\nXe’ra est peut-être tombée, mais je perçois toujours sa présence à nos côtés. La Lumière qui brillait dans son cœur peut toujours insuffler force et vigueur à notre cause.\n\nSa perte a dû frapper Turalyon de plein fouet. Je ferai de mon mieux pour apaiser son esprit troublé. De votre côté, tâchez de rassembler les derniers vestiges de la mère la Lumière.', '', '', '', '', '', '', 25996),
(49135, 'frFR', 'Antorus, le Trône ardent : le cœur d’Argus', 'Récupérez les 4 Cachets du titan noir sur Aggramar à Antorus, le Trône ardent, en mode mythique.', 'Hatuun m’a confié qu’après la chute d’Argus, Sargeras a fait ériger un temple de ténèbres dans les profondeurs du noyau de la planète. On ignore presque tout de cet édifice ; jusqu’ici, seuls les disciples les plus dévoués du titan noir se sont vu donner les cachets permettant d’y pénétrer.\n\nSi nous nous en emparons, nous pourrons en imprégner le Vindicaar, et ainsi mener l’assaut contre l’infâme cœur d’Argus de front.', '', '', '', '', '', '', 25996),
(49134, 'frFR', 'Antorus, le Trône ardent : le cœur d’Argus', 'Récupérez les 4 Cachets du titan noir sur Aggramar à Antorus, le Trône ardent, en mode héroïque.', 'Hatuun m’a confié qu’après la chute d’Argus, Sargeras a fait ériger un temple de ténèbres dans les profondeurs du noyau de la planète. On ignore presque tout de cet édifice ; jusqu’ici, seuls les disciples les plus dévoués du titan noir se sont vu donner les cachets permettant d’y pénétrer.\n\nSi nous nous en emparons, nous pourrons en imprégner le Vindicaar, et ainsi mener l’assaut contre l’infâme cœur d’Argus de front.', '', '', '', '', '', '', 25996),
(49133, 'frFR', 'Antorus, le Trône ardent : le cœur d’Argus', 'Récupérez les 4 Cachets du titan noir sur Aggramar à Antorus, le Trône ardent, en mode normal.', 'Hatuun m’a confié qu’après la chute d’Argus, Sargeras a fait ériger un temple de ténèbres dans les profondeurs du noyau de la planète. On ignore presque tout de cet édifice ; jusqu’ici, seuls les disciples les plus dévoués du titan noir se sont vu donner les cachets permettant d’y pénétrer.\n\nSi nous nous en emparons, nous pourrons en imprégner le Vindicaar, et ainsi mener l’assaut contre l’infâme cœur d’Argus de front.', '', '', '', '', '', '', 25996),
(49099, 'frFR', 'Site d’invasion : Bonic', '', '', '', '', '', '', '', '', 25996),
(49098, 'frFR', 'Site d’invasion : Cen’gar', '', '', '', '', '', '', '', '', 25996),
(49097, 'frFR', 'Site d’invasion : Sangua', '', '', '', '', '', '', '', '', 25996),
(49096, 'frFR', 'Site d’invasion : Naigtal', '', '', '', '', '', '', '', '', 25996),
(49091, 'frFR', 'Site d’invasion : Val', '', '', '', '', '', '', '', '', 25996),
(49077, 'frFR', 'Moments de réflexion', 'Apportez le Cristal d’Illidan aux personnes et aux endroits qui lui sont chers.', '<La magie ensorceleuse qui émane du cristal vous attire.\n\nQuand vous vous en emparez, vous entendez l’écho du message qu’il contient, une tâche qu’Illidan vous a confiée.>', '', '', '', '', '', '', 25996),
(49076, 'frFR', 'Antorus, le Trône ardent : passage obscur', 'Récupérez les 4 Runes de passage d’Imonar le Chasseur d’âmes à Antorus, le Trône ardent, en mode mythique.', 'Malgré les dangereuses énergies qui s’échappent du cœur d’Argus, le vaisseau du Chasseur d’âmes se déplace librement dans le Trône ardent. D’après nos éclaireurs, il serait en mesure de gagner le Sanctechœur corrompu grâce au pouvoir de plusieurs runes démoniaques.\n\nSi elles étaient entre notre possession, le Vindicaar pourrait faire de même et nous troupes gagneraient un temps précieux.', '', '', '', '', '', '', 25996),
(49075, 'frFR', 'Antorus, le Trône ardent : passage obscur', 'Récupérez les 4 Runes de passage d’Imonar le Chasseur d’âmes à Antorus, le Trône ardent, en mode héroïque.', 'Malgré les dangereuses énergies qui s’échappent du cœur d’Argus, le vaisseau du Chasseur d’âmes se déplace librement dans le Trône ardent. D’après nos éclaireurs, il serait en mesure de gagner le Sanctechœur corrompu grâce au pouvoir de plusieurs runes démoniaques.\n\nSi elles étaient entre notre possession, le Vindicaar pourrait faire de même et nous troupes gagneraient un temps précieux.', '', '', '', '', '', '', 25996),
