UPDATE `quest_template_locale` SET `QuestDescription`='Je pense que nous pouvons utiliser cet indice à notre avantage, $n.$b$bC’est bien connu, les Flétris sont assoiffés de mana et ne reculent devant rien pour s’en procurer. Peut-être pouvons-nous étudier l’usage qu’ils font de l’aethril afin d’améliorer nos propres techniques de cueillette.', `VerifiedBuild`=25996 WHERE (`ID`=40016 AND `locale`='frFR');
UPDATE `quest_template_locale` SET `LogDescription`='Parlez à Kuhuine Tendre-Pas de l’aethril et des Flétris.', `QuestDescription`='Des lambeaux d’étoffe raffinée, déchirés et souillés, voilà qui est typique des Flétris.$b$bLes parias sauvages et dégénérés de la société sacrenuit exploitent également l’aethril, semble-t-il… La question est, pourquoi ?', `VerifiedBuild`=25996 WHERE (`ID`=40015 AND `locale`='frFR');
