UPDATE `quest_template_locale` SET `QuestDescription`='Les vers n’aiment pas se battre, et ils détestent le monde de la surface. Ils ne font qu’aller là où leur maître leur dit d’aller.$b$bAlors, en temps de guerre, c’est lui qu’il faut tuer.$b$bLe siègebrouf Olgrouf est le maître des Drogbars pierre-puissance qui nous attaquent depuis le nord.$b$bDébarrassez-nous de lui.', `VerifiedBuild`=25996 WHERE (`ID`=39862 AND `locale`='frFR');
