UPDATE `quest_template_locale` SET `LogDescription`='Récupérez $oa Fioles de gangresang sur les Gangr’orcs dans la Jungle de Tanaan.', `QuestDescription`='Les Orcs qui boivent le poison de Gul’dan, ils se transforment en bêtes. Des sauvages sans âme.$b$bDame Liadrin et les chevaliers de sang, ils pensent que c’est pas irréversible. Ils veulent des échantillons du sang des Orcs qui ont été transformés y a pas longtemps. Prenez leur sang, $n !$b$bLes Gangr’orcs, vous les trouverez dans tout Tanaan, mais là où y en a le plus, c’est au Front de Fer, à la Gangreforge et au Trône de Kil’jaeden.', `VerifiedBuild`=25996 WHERE (`ID`=39511 AND `locale`='frFR');
