UPDATE `quest_template_locale` SET `QuestDescription`='Les feux follets sont les esprits de nos frères Elfes de la nuit unis avec la forêt pour ne faire plus qu’un. Leur perception et leur vue du monde sont bien différents de ceux des vivants.$b$bVous devriez vous lier avec ce petit être. Observez par ses yeux alors qu’il se rend aux bassins cachés et fait pousser des arbres.', `VerifiedBuild`=25996 WHERE (`ID`=39354 AND `locale`='frFR');
