UPDATE `quest_template_locale` SET `LogTitle`='Les Taurens pris au piège', `QuestDescription`='Les Drogbars ont rassemblé autant des nôtres que possible et les ont conduits dans une grotte à proximité.\n\nSi vous faites vite, je crois qu’il est encore possible de les sauver. J’ignore dans quel but ils nous capturent.\n\nMais rien que d’y penser, j’en frémis… dans ces profondeurs, tout n’est que ténèbres.', `VerifiedBuild`=25996 WHERE (`ID`=39316 AND `locale`='frFR');
