UPDATE `quest_template_locale` SET `QuestDescription`='Les tribus de Haut-Roc comptaient prêter allégeance à vos forces, car nous savons que la Légion ardente est entrée en guerre.$b$bHélas, nous avons été trahis et devons désormais vous demander votre aide.$b$bUne grande relique, le marteau de Khaz’goroth, nous a été dérobée par les ignobles Drogbars.$b$bNous avons besoin de vous pour la récupérer.', `VerifiedBuild`=25996 WHERE (`ID`=38907 AND `locale`='frFR');
