UPDATE `quest_template_locale` SET `QuestDescription`='$gMineur:Mineuse;… vous… vous savez qui je suis ?$b$bJe vois. C’est une bonne chose. Ma tribu continue à honorer ses racines.$b$bSi vous retournez sur les terres de la tribu des Cornes-de-Fer… dites-leur que leurs ancêtres les regardent avec fierté.', `VerifiedBuild`=25996 WHERE (`ID`=38793 AND `locale`='frFR');
UPDATE `quest_template_locale` SET `QuestDescription`='Vous… $gmineur:mineuse;… laissez-moi regarder votre pioche un instant.$b$b<L’esprit du Tauren observe votre équipement de $gmineur:mineuse;.>$b$bVous me faites penser à moi, quand j’ai foulé cette terre pour la première fois, jadis. Savourez cet instant, $gmineur:mineuse;. Il ne durera pas éternellement.$b$b<Et, sur un dernier salut, l’esprit disparaît.>', `VerifiedBuild`=25996 WHERE (`ID`=38792 AND `locale`='frFR');
UPDATE `quest_template_locale` SET `QuestDescription`='Vous avez récupéré sur le corps de la créature de pierre un trésor des plus atypiques : un morceau de corne de Tauren extrêmement endommagé.$b$bIl est visiblement très, très vieux, mais quelque chose dans sa couleur et sa courbure vous rappelle Ronos Corne-de-Fer, de l’enclave des Cornes-de-Fer.', `VerifiedBuild`=25996 WHERE (`ID`=38791 AND `locale`='frFR');
