UPDATE `quest_template_locale` SET `QuestDescription`='L’Elfe de la nuit portait une chevalière gravée des armoiries des Gardiennes.$B$BL’anneau, façonné à partir d’un métal argenté incassable, est usé par le temps, comme si sa propriétaire l’avait fait tourner distraitement autour de son doigt encore et encore.', `VerifiedBuild`=25996 WHERE (`ID`=38711 AND `locale`='frFR');
