UPDATE `quest_template_locale` SET `QuestDescription`='Ma récolte estivale de maïs n’attend plus que d’être moissonnée. J’ai besoin de bras pour la mettre à l’abri avant que les Elfes de la nuit ne me la détruisent.$B$BSi vous vous en chargez, je vous récompenserai généreusement.$B$BLes villageois ont besoin de cette nourriture, et pour ma part, j’en ai ma claque du civet de rat !', `VerifiedBuild`=25996 WHERE (`ID`=38647 AND `locale`='frFR');
