UPDATE `quest_template_locale` SET `LogDescription`='Utilisez un Grappin rochenoire pour atteindre le fortin de Knar. Tuez-le afin de récupérer le Plan de chantier naval de Roark.', `VerifiedBuild`=25996 WHERE (`ID`=38572 AND `locale`='frFR');
