UPDATE `quest_template_locale` SET `QuestDescription`='À la crête de Givrefeu, un sage sire-tonnerre du nom d’Argoram semble avoir localisé l’emplacement d’une arme chargée d’histoire, connue des Orcs sous le nom de Fléau-des-Gronns.\n\nLa dernière fois qu’on l’a vu, il se dirigeait vers Magnarok. Trouvez-le et voyez s’il peut vous conduire à cette relique.', `VerifiedBuild`=25996 WHERE (`ID`=37914 AND `locale`='frFR');
