UPDATE `quest_template_locale` SET `QuestDescription`='Oh, c’était horrible.$b$bMon mari et moi étions en train de pêcher dans le marécage, puis je me suis endormie. À mon réveil, il avait été transformé en crapaud !$b$bJe suis persuadée que c’est le fait de l’un de ces Orcs ombrelunes dont on parle tant.$b$bIl a alors sauté dans les eaux boueuses avant que je ne puisse le rattraper.$b$bAcceptez-vous de m’aider à retrouver l’amour de ma vie, $c ?', `VerifiedBuild`=25996 WHERE (`ID`=34876 AND `locale`='frFR');
