UPDATE `quest_template_locale` SET `QuestDescription`='Commandant, je vais ordonner à mes troupes de sécuriser ce passage, mais à titre personnel je ne compte pas rester les bras croisés pendant que l’ennemi se prépare à lancer une nouvelle attaque.$b$bJe compte frapper la Horde de Fer le premier, sur son terrain à Rochenoire, et pour ce faire nous allons devoir nous rendre là où peu d’Orcs osent mettre les pieds.$b$bJe veux parler de Gorgrond.$b$bC’est une contrée sauvage infestée de géants et de monstres de toutes sortes.$b$bQue diriez-vous de m’y accompagner pour démolir les fonderies de la Horde de Fer ?', `VerifiedBuild`=25996 WHERE (`ID`=34867 AND `locale`='frFR');
