UPDATE `quest_template_locale` SET `QuestDescription`='Les mauvais Orcs ont tenté de m’attraper, mais j’ai réussi à fuir. Je me cache comme personne.$b$bTous les mauvais orcs sont mauvais, mais j’ai mémorisé le nom des plus méchants, au cas où on viendrait me sauver.$b$b<Luuka inspire profondément.>$b$bUngra, Gurran et… hum… oh ! Ankova.$b$bAllez-vous me protéger d’eux ?', `VerifiedBuild`=25996 WHERE (`ID`=34431 AND `locale`='frFR');
