UPDATE `quest_template_locale` SET `QuestDescription`='Les Orcs des environs ont l’air d’appartenir au clan de la Main-Brisée. Il suffit de regarder leurs mains pour le savoir.$b$bAllons rejoindre les autres. Nous devons trouver un moyen de quitter cet endroit.', `VerifiedBuild`=25996 WHERE (`ID`=34425 AND `locale`='frFR');
