UPDATE `quest_template_locale` SET `QuestDescription`='Nos druides ont mis sur pied un grand réseau d’éclaireurs suite aux informations que vous avez rapportées de Nagrand.$B$BNous avons repéré une excavation suspecte de la Horde de Fer à proximité des marais salants situés sur la côte ouest de Gorgrond.$B$BNous avons de bonnes raisons de penser que ces Orcs sont à la recherche d’un artéfact précieux enfoui dans le désert.$B$BJe suis en train d’organiser une mission pour opérer une frappe chirurgicale. J’aimerais que vous fassiez partie de l’équipe.', `VerifiedBuild`=25996 WHERE (`ID`=34409 AND `locale`='frFR');
