UPDATE `quest_template_locale` SET `QuestDescription`='Un problème très grave est survenu. Durant votre absence, l’archimage Khadgar a pris contact avec moi.$B$BIl étudie l’influence démoniaque au nord.$B$BComme c’est un Humain, les Loups-de-Givre ne l’accepteront pas si vous ne pouvez répondre de lui. Et ils n’accepteront pas plus une Elfe de la nuit comme moi.$B$BJe vous attendrai à l’extérieur de Throm’var, dans la combe de Givrevent.', `VerifiedBuild`=25996 WHERE (`ID`=34209 AND `locale`='frFR');
