UPDATE `quest_template_locale` SET `QuestDescription`='Les Orcs ombrelunes ne se sont pas tous alliés à la Horde de Fer comme Ner’zhul.$B$BIl y a parmi eux une Orque qui est devenue mon amie, il y a de nombreuses années. Elle pourra peut-être nous en apprendre plus sur les plans de Ner’zhul concernant cette « Étoile noire ».$B$BVous la trouverez à la cime de l’Exilé, au nord-est. Je la ferai prévenir de votre arrivée.', `VerifiedBuild`=25996 WHERE (`ID`=33586 AND `locale`='frFR');
