UPDATE `quest_template_locale` SET `QuestDescription`='Un des hurleciel des Trolls de Za’Tual est en train de subir un rituel de torture, et sa volonté pervertie à jamais pour servir ses maîtres.\n\nTuez ceux qui infligent un tel tourment à cette créature et avec un peu de chance, elle retournera dans les cieux.', `VerifiedBuild`=25996 WHERE (`ID`=32544 AND `locale`='frFR');
