UPDATE `quest_template_locale` SET `QuestDescription`='Nous ne pouvons PAS permettre que les Orcs établissent une tête de pont sur ces terres. Ils les profaneraient comme ils l’ont fait en Kalimdor.$b$b$p, quelqu’un doit se rendre sur le terrain pour que la Horde rejoigne sa tombe. Rendez-vous sur la côte et faites pleuvoir sur eux toute la puissance du courroux de l’Alliance !$b$bTuez tous les Orcs que vous rencontrerez. Rabattez-leur leur caquet.$b$bPour le roi !', `VerifiedBuild`=25996 WHERE (`ID`=32142 AND `locale`='frFR');
