UPDATE `quest_template_locale` SET `QuestDescription`='Je ne laisserai PAS la Horde poser ne fût-ce qu’un orteil sur ces côtes avant nous ! Si vous avez envie de vous jeter dans la bataille, un gyrocoptère vous attend au bout de la piste. Une attaque est déjà prévue, tout ce que vous avez à faire est de vous concentrer sur vos tirs.$B$BFaites pleuvoir l''enfer sur ces Orcs !', `VerifiedBuild`=25996 WHERE (`ID`=31732 AND `locale`='frFR');
