UPDATE `quest_template_locale` SET `QuestDescription`='Mes rêves se font vagues ces derniers temps, $R.$B$BJ’ai besoin d’un truc bien fort pour me remettre en selle !$B$BJ’ai entendu parler d’une nouvelle boisson locale dél-hic-cieuse.$B$BÇa s’appelle la mixture de la sorcière de jade.$B$BJ’adorerais y goûter.', `VerifiedBuild`=25996 WHERE (`ID`=31322 AND `locale`='frFR');
UPDATE `quest_template_locale` SET `QuestDescription`='Héééé c’est $gmon pote le:ma pote la:r; $R !$B$BChuis sûr que vous m’avez vu traîner dans le coin, mais j’dois vous dire que chuis pas choûl.$B$BJ’veux dire, regardez-moi un peu ! Plus chobre encore qu’un poisson d’eau douche !$B$BBien chûr, de temps en temps, j’aime bien noyer mes chouchis dans d’la bonne gnôle. Mais un jinyu n’est jamais choûl ! Autant echayer de noyer un poichon !$B$BNon, la gnôle me fait dormir et quand je dors, je vois l’avenir.$B$BPlus forte est la gnôle, plus puichants chont mes rêves ! Si vous m’en rapportez de la bonne, je vous révèlerai votre avenir.', `VerifiedBuild`=25996 WHERE (`ID`=31321 AND `locale`='frFR');
