UPDATE `quest_template_locale` SET `QuestDescription`='D''accord d''accord, $gmon pote:ma grande;. On va commencer petit. Faut que j’m’assure ‘‘vous savez vous servir de cette arme qu’vous trimballez avec vous.$B$BAllez m’casser des cibles tiki. En douceur. Naturellement. J’vais vous regarder vous escrimer, et on partira d’là.', `VerifiedBuild`=25996 WHERE (`ID`=31158 AND `locale`='frFR');
