UPDATE `quest_template_locale` SET `QuestDescription`='Les hozen casse-dent ont volé notre Patte de Lapin ! C’était le grumelot le plus veinard d’entre nous.$b$bC’est vraiment pas de chance, hein ? Je vous en prie, $R, il faut que nous récupérions notre Patte de lapin. Nous avons besoin de sa bonne fortune.$b$bPouvez-vous partir à sa recherche à l’avant-poste de Casse-Dent ?', `VerifiedBuild`=25996 WHERE (`ID`=30602 AND `locale`='frFR');
