UPDATE `quest_template_locale` SET `QuestDescription`='Les hordes d’Utgarde se rassemblent sous le commandement du prince Keleseth, un ambassadeur san''layn de la Horde.$B$BNous ne pouvons tolérer que les Vrykuls profitent plus longtemps de ses conseils. Faites-le donc taire !', `VerifiedBuild`=25996 WHERE (`ID`=30112 AND `locale`='frFR');
