UPDATE `quest_template_locale` SET `QuestDescription`='La terre des Trolls des glaces, elle est plus que l’ombre de sa gloire qu’est passée.$b$bSi vous avez du courage, vous allez chercher les tablettes de l’histoire qui racontent pourquoi l’empire drakkari il a fini comme ça.$B$BPeut-être qu’un jour, cette terre, on pourra la transmettre à une nouvelle génération de Trolls des glaces.', `VerifiedBuild`=25996 WHERE (`ID`=29844 AND `locale`='frFR');
