UPDATE `quest_template_locale` SET `QuestDescription`='Tout ce bazar il aurait pu être évité si les Trolls ils avaient servi les dieux au lieu de les détruire.$b$bJ’ai appris qu’ils ont un golem spécial, un golem qui est imprégné d’une puissance interdite.$b$bRapportez-moi un morceau de ce golem pour qu’on en apprenne plus sur nos frères et nos sœurs.', `VerifiedBuild`=25996 WHERE (`ID`=29839 AND `locale`='frFR');
