UPDATE `quest_template_locale` SET `QuestDescription`='Le puissant Akali il a été tué, $R.$b$bMon wôle dans la vie, il est d’enwegistrer, pas de combattre. Mais cet acte, il ne doit pas wester impuni ! Gal’darah et ses complices ils doivent payer !$b$bVengez la mowt d’Akali, mec. C’est la bonne chose à faiwe.', `VerifiedBuild`=25996 WHERE (`ID`=29835 AND `locale`='frFR');
