UPDATE `quest_template_locale` SET `QuestDescription`='Autrefois, je considérais l''Ancien Nadox comme mon maître.$B$BMais il ne l’est plus, et ne le sera plus jamais, depuis qu’il s’est mis au service des damnés et m’a contraint à assister au massacre impitoyable de mes amis et de ma famille.$B$BTrouvez-le dans les profondeurs et faites-le payer pour ses crimes, $R.', `VerifiedBuild`=25996 WHERE (`ID`=29825 AND `locale`='frFR');
