UPDATE `quest_template_locale` SET `QuestDescription`='Le Faiseur crée plus de Gangr’orcs en les infusant de sang de démon.$B$BMes supérieurs pensent pouvoir inverser le processus, mais nous avons besoin d’échantillons de leur sang, ainsi que du bâtonnet d’infusion du Faiseur, pour nous en assurer.', `VerifiedBuild`=25996 WHERE (`ID`=29535 AND `locale`='frFR');
