UPDATE `quest_template_locale` SET `QuestDescription`='Tous les membres de la Horde en état de porter les armes sont sommés de se présenter à Kadrak au rempart de Mor’shan, sur la frontière entre les Tarides du Nord et Orneval. Aidez nos forces à bouter les Elfes de la nuit hors de la forêt afin que nous utilisions ses ressources pour notre population !$b$bPour vous rendre au rempart de Mor’shan, suivez la route de l’Or vers le nord en partant de la Croisée, dans les Tarides du Nord.$b$bVotre destin vous appelle !', `VerifiedBuild`=25996 WHERE (`ID`=28493 AND `locale`='frFR');
