UPDATE `quest_template_locale` SET `QuestDescription`='Vous allez l’adorer, celui-là ! Les Marteaux-hardis ont appris que vous entriez dans l’arène, et ils sont bien déterminés à ce que vous ne la quittiez pas $gvivant:vivante;.$B$BC’est le moment de voir un beau duel $R contre nain ! Dites-moi quand vous serez $gprêt:prête; !', `PortraitTurnInText`='Rien ne vaut l''affection d''un Troll !', `VerifiedBuild`=25996 WHERE (`ID`=27865 AND `locale`='frFR');
UPDATE `quest_template_locale` SET `QuestDescription`='Vous allez l’adorer, celui-là ! Les Gueules-de-dragon ont appris que vous entriez dans l’arène, et ils sont bien déterminés à ce que vous ne la quittiez pas $gvivant:vivante;.$B$BC’est le moment de voir un beau duel $R contre Orc ! Dites-moi quand vous serez $gprêt:prête; !', `PortraitTurnInText`='Rien ne vaut l''affection d''un Troll !', `VerifiedBuild`=25996 WHERE (`ID`=27864 AND `locale`='frFR');
