UPDATE `quest_template_locale` SET `QuestDescription`='Je connais un Humain appelé Paval Reethe. Pathétique, même pour ses semblables ! Il a déserté son camp et se cache maintenant dans les bois.$b$bJ’ai envoyé Ogron pour le traquer. Certains le suspectent de voler notre ravitaillement. Je crois que j’ai vu Ogron aller vers le sud-est.', `VerifiedBuild`=25996 WHERE (`ID`=27306 AND `locale`='frFR');
