UPDATE `quest_template_locale` SET `QuestDescription`='Je doute que les Totems-Sinistres abandonnent leur campagne visant à chasser les Humains du marécage, même si j’ai l’impression que vous vous en fichez. Mais au moins, nous nous sommes chargés des coupables des crimes perpétrés à l’auberge du Repos ombragé.$B$BAllez dire à votre chef que sa soif de vengeance a été apaisée.', `VerifiedBuild`=25996 WHERE (`ID`=27297 AND `locale`='frFR');
