UPDATE `quest_template_locale` SET `QuestDescription`='À l’ouest, au plus profond d’Andorhal, se trouvent les commandants de l’Alliance. Ils ne prennent pas part aux hostilités, mais lancent leurs ordres du haut de leurs montures.$b$bTraquez et tuez ces commandants, $n. Les Humains seront condamnés à la défaite.', `VerifiedBuild`=25996 WHERE (`ID`=27086 AND `locale`='frFR');
