UPDATE `quest_template_locale` SET `LogTitle`='Le Troll cérébral', `QuestDescription`='La vision télépathique, elle n''est pas suffisante, non.$B$BLe contrôle mental, ça c''est une magie beaucoup plus forte, oui.$B$BLa magie puissante, elle a besoin de réactifs puissants. Le cerveau de Troll, c''est un réactif puissant, oui.$b$bBraddok de Zul''Mamwe, c''est un Troll très malin, oui.$B$BVous allez vers le sud, et vous trouvez le gros cerveau de Braddok.', `VerifiedBuild`=25996 WHERE (`ID`=26774 AND `locale`='frFR');
