UPDATE `quest_template_locale` SET `QuestDescription`='Il ne reste plus que les réfugiés du quartier général rochenoire, $n. Ils se sont tous barricadés dans le donjon de Guet-de-Pierre, juste au sud du poste de Keeshan. Je veux que la compagnie Bravo et vous entriez dans Guet-de-Pierre et mettiez fin à l’invasion des Orcs rochenoires.$B$BQu’il n’y ait aucun survivant, $n !', `VerifiedBuild`=25996 WHERE (`ID`=26713 AND `locale`='frFR');
