UPDATE `quest_template_locale` SET `QuestDescription`='Vous avez l’air d’être $gdoué:douée;, $R. Quelqu’un doit plonger dans le chaos du front pour aller soigner nos soldats blessés.$B$BPrenez ma trousse. Elle est assez simple d’utilisation.$B$BSoignez-les avant que les troggs de pierre ne les achèvent pour de bon.', `VerifiedBuild`=25996 WHERE (`ID`=26591 AND `locale`='frFR');
