UPDATE `quest_template_locale` SET `QuestDescription`='Mon initié de Gobelin est parti depuis un bon moment. Il s’appelle Minelor.$B$BJe l’ai envoyé observer les écorche-rocs de la région, au sud-ouest, vers le bassin de Quartzite. Vous pourriez peut-être partir à sa recherche ? Quand vous l’aurez trouvé, demandez-lui de revenir au temple.', `VerifiedBuild`=25996 WHERE (`ID`=26409 AND `locale`='frFR');
