UPDATE `quest_template_locale` SET `LogDescription`='Lard, du village des Vengebroches, dans les Hinterlands, veut que vous retrouviez le Repas de Lard. Retournez le voir lorsque ce sera fait.$B$BD’après Lard, il l’aurait laissé dans l’île, au nord. Prenez garde aux Trolls vilebranches !', `VerifiedBuild`=25996 WHERE (`ID`=26212 AND `locale`='frFR');
