UPDATE `quest_template_locale` SET `QuestDescription`='<Grimeo place vos trouvailles dans un paquet qu’il enveloppe avec soin.>$B$BVoilà, c’est là tout ce que le Gnome nous a demandé. Quand vous le verrez, dites-lui bien que nous sommes quittes, lui et moi. Je n’accepterai plus ses demandes, à l’avenir.', `VerifiedBuild`=25996 WHERE (`ID`=26166 AND `locale`='frFR');
