UPDATE `quest_template_locale` SET `QuestDescription`='Ouf ! Il était moins une. Je n’aurais jamais cru qu’on en réchapperait, $n. On ferait bien d’apporter ces pièces à l’explogénieur en chef Bombetripes. Je crois déjà entendre le bourdonnement des machines volantes des Gnomes, à l’extérieur. Il n’y a pas une minute à perdre !', `VerifiedBuild`=25996 WHERE (`ID`=26048 AND `locale`='frFR');
