UPDATE `quest_template_locale` SET `QuestDescription`='Que… qu’est-ce qui m’arrive ?!$b$bUne douleur atroce… dans mes tripes.$b$bJe crois… aïe… qu’ils m’ont empoisonné !$b$bIls nous donnaient des algues bizarres à manger, des algues luminescentes qui poussent autour de leur forteresse…$b$bJe pense que ces crampes s’aggraveront si on ne m’en donne pas à manger très bientôt…$b$bJe vous en prie, $R. Essayez de m’en trouver !', `VerifiedBuild`=25996 WHERE (`ID`=26040 AND `locale`='frFR');
