UPDATE `quest_template_locale` SET `QuestDescription`='Vous avez entendu ce qu’a dit le commandant, $n. Allez porter mon chef-d’œuvre culinaire à l’ambassadeur du Totem-Sinistre ! Il vous attend avec sa suite au bout du sentier du sud-est.$b$bJe vous garantis que grâce à ce plat, on va avoir le chef des Taurens à la bonne !', `VerifiedBuild`=25996 WHERE (`ID`=25844 AND `locale`='frFR');
