UPDATE `quest_template_locale` SET `VerifiedBuild`=25996 WHERE (`ID`=25591 AND `locale`='frFR');
UPDATE `quest_template_locale` SET `QuestDescription`='Dites-moi, $n, vous n’auriez pas vu mon autre frère, Lachnouf, par hasard ?$B$BJ’ai bien l’impression que les pirates l’ont capturé ! La dernière chose qu’il m’a dite, c’est qu’il allait essayer de leur vendre des trucs d’ingénierie et tout ça.$b$bVous voulez bien aller voir s’il n’est pas enfermé à la redoute de mers du Sud, à l’est ? Je suis sûr que c’est ce bon à rien de Gobelin de Synge avec qui il est toujours fourré qui l’a mis dans le pétrin.', `VerifiedBuild`=25996 WHERE (`ID`=25590 AND `locale`='frFR');
