UPDATE `quest_template_locale` SET `QuestDescription`='Je vous en supplie, $R ! Vous devez m’aider !$b$bJe n’ai survécu que de justesse avec tous ces nagas, ces requins et cet horrible monstre qui a attaqué notre navire.$b$bÉcoutez, j’ai remarqué une caverne qui a l’air d’être inhabitée, mais je n’ose pas y aller à moins d’être sûre qu’il y a une poche d’air à l’intérieur.$b$bVous voulez bien aller vérifier pour moi ?', `VerifiedBuild`=25996 WHERE (`ID`=25587 AND `locale`='frFR');
