UPDATE `quest_template_locale` SET `QuestDescription`='Ces mi-portions de Gnomes ridicules et insensibles aux charmes des explosions ont dépassé les bornes !$b$bJe veux que vous fassiez une descente au bar de la péniche de course, que vous commandiez une bouteille de grog, et que vous la fracassiez sur le crâne d’un Gnome !$b$bMontrez-leur que nous en avons assez de leur arrogance, $n !', `VerifiedBuild`=25996 WHERE (`ID`=25518 AND `locale`='frFR');
