UPDATE `quest_template_locale` SET `QuestDescription`='Nous y voilà. Voici le discours, $n!$B$BIl a tout pour motiver les troupes : il est stimulant, éloquent et il parle directement aux Gnomes. On n''a jamais écrit un aussi bon discours !$B$BRapportez-le au capitaine Chape Étincetuyère et allez voir le Grand Bricoleur Mekkanivelle par le premier transport.', `VerifiedBuild`=25996 WHERE (`ID`=25286 AND `locale`='frFR');
