UPDATE `quest_template_locale` SET `QuestDescription`='Je veux voir des Gobelins crevés, $n ! Juste à l’ouest, vous trouverez toute une fourmilière grouillante de ces petits insectes creusant la montagne.$B$BFaites en sorte que cette infâme taupinière soit leur tombeau.$B$BÉradiquez-les. Dévastez toute leur sale machinerie. Ils ont semé le germe de leur propre destruction à Bael’dun, $c. Maintenant, il est temps de faucher.', `VerifiedBuild`=25996 WHERE (`ID`=25182 AND `locale`='frFR');
