UPDATE `quest_template_locale` SET `QuestDescription`='Prêtez-moi l’oreille, $c !$b$bLes vents du changement soufflent en tempête, balayant tout Azeroth.$b$bAurez-vous la force d’affronter la véritable cause de nos malheurs ?$b$bRassemblez votre courage, $R, et priez pour avoir assez de chance et d’énergie pour faire face à ce qui nous attend.$b$BUn allié inattendu appelle tous ceux qui voudront bien l’entendre. Penchez-vous sur les Eaux de longue-vision, et contemplez le destin du monde !', `VerifiedBuild`=25996 WHERE (`ID`=14446 AND `locale`='frFR');
