UPDATE `quest_template_locale` SET `PortraitGiverText`='Lorsque Malfurion a arraché les restes de Xavius de Teldrassil, l’Arbre-monde a été libéré d’un grand poids. Un vestige de Xavius demeure pour tourmenter les Elfes, mais le champion d''Élune qui libérera entièrement l''arbre approche.', `VerifiedBuild`=25996 WHERE (`ID`=14005 AND `locale`='frFR');
