UPDATE `quest_template_locale` SET `QuestDescription`='Aujourd’hui, la chance nous sourit, $R.$b$bLe sang de Gorat était assez frais et j’ai donc pu réaliser un rituel très particulier que je connais depuis l’enfance.$b$bAppliquez ce sang imprégné sur le cadavre de Gorat pour invoquer son esprit errant. Écoutez-le, faites ce qu’il vous demandera, puis revenez informer Kadrak de la situation.$b$bPuissent les esprits vous protéger, mon $gami:amie;.', `VerifiedBuild`=25996 WHERE (`ID`=13621 AND `locale`='frFR');
