UPDATE `quest_template_locale` SET `QuestDescription`='Nous nous rencontrons à nouveau, $R. Je le confesse, votre présence commence à m''être sympathique.$b$bAi-je raison de croire que vous venez perfectionner vos compétences en combat aérien ?$b$bComme toujours, mes familiers sont prêts à faire pleuvoir la destruction sur l''ennemi.$b$bParlez, et ils seront à votre disposition.', `VerifiedBuild`=25996 WHERE (`ID`=13414 AND `locale`='frFR');
