UPDATE `quest_template_locale` SET `VerifiedBuild`=25996 WHERE (`ID`=11681 AND `locale`='frFR');
UPDATE `quest_template_locale` SET `QuestDescription`='La clé est forgée à nouveau.$b$bÉcoutez bien mon conseil maintenant, $R. Réussissez ou bien mourez lors de votre tentative, car si une seule écaille tombe de l''un de mes drakes, je vous en tiendrai pour personnellement responsable.$b$bPartez maintenant.', `VerifiedBuild`=25996 WHERE (`ID`=11680 AND `locale`='frFR');
