UPDATE `quest_template_locale` SET `LogDescription`='Apportez une Commande du téléporteur de la Légion au chef d''escadrille Nuainn au bastion des Marteaux-Hardis. On sait que les Fabricants d''armes mo''arg du bastion de la Légion portent ces appareils.', `VerifiedBuild`=25996 WHERE (`ID`=10589 AND `locale`='frFR');
