UPDATE `quest_template_locale` SET `LogTitle`='Où sont passés ces fichus Gnomes ?', `LogDescription`='Fouillez la zone sud de la Crête dentelée, dans les Tranchantes pour y trouver des indices quant à l''endroit où pourraient se trouver Toshley et les autres Gnomes.', `VerifiedBuild`=25996 WHERE (`ID`=10580 AND `locale`='frFR');
