UPDATE `quest_template_locale` SET `LogDescription`='Trouvez un Miroir des âmes quelque part dans les cryptes Auchenaï et utilisez-le pour invoquer un Esprit assombri issu des Ancêtres d''anciens Orcs en Nagrand. Détruisez 15 Esprits assombris afin que les ancêtres puissent reposer en paix.$B$BRetournez voir Mère Kashur dans les Terres ancestrales lorsque vous aurez terminé cette tâche.', `VerifiedBuild`=25996 WHERE (`ID`=10168 AND `locale`='frFR');
