UPDATE `quest_template_locale` SET `LogDescription`='Remettez la Communication des Elfes de sang à l’exarque Menelaous au Guet d’azur.', `QuestDescription`='On dirait une liste de trophées. Vous ne comprenez pas la langue, mais vous remarquez une image représentant le cadavre d’un Draeneï, un Elfe de sang souriant au-dessus de lui, et un symbole que vous associez à la monnaie des Elfes de sang.$B$BIls ont traqué un Draeneï ! Vous devez en informer l’exarque.', `VerifiedBuild`=25996 WHERE (`ID`=9616 AND `locale`='frFR');
