UPDATE `quest_template_locale` SET `QuestDescription`='Allez au village de Brise-Clémente et prévenez le forestier Degolien des plans des Amani. En dépit de la mort de Zul’Marosh, Brise-Clémente doit se préparer à une attaque de Trolls. Dites à Degolien que je lui enverrai des renforts dès que possible.', `VerifiedBuild`=25996 WHERE (`ID`=9363 AND `locale`='frFR');
