UPDATE `quest_template_locale` SET `QuestDescription`='Vous nous avez beaucoup aidés à vaincre les Déshérités. Les pérégrins ont toujours besoin de gens comme vous pour participer à leur combat contre les Trolls Amani.$B$BRendez-vous à la Retraite des Pérégrins, au nord-est d''ici. Adressez-vous au lieutenant Coursaurore, et voyez si vous pouvez l’aider.', `VerifiedBuild`=25996 WHERE (`ID`=9359 AND `locale`='frFR');
