UPDATE `quest_template_locale` SET `LogDescription`='L’apprenti Vor’el, au domaine d’Andilien dans les Terres Fantômes, veut que vous tuiez 10 Filetoiles supérieures et 10 Ravageurs Griffes-fantômes.', `VerifiedBuild`=25996 WHERE (`ID`=9281 AND `locale`='frFR');
