UPDATE `quest_template_locale` SET `LogDescription`='Tuez 5 Yeux de Dar''Khan, 6 Centurions nérubis et 6 Pleureuses à Mortholme, puis retournez voir le magistère Idonis au sanctum du Soleil dans les Terres Fantômes.', `VerifiedBuild`=25996 WHERE (`ID`=9220 AND `locale`='frFR');
