UPDATE `quest_template_locale` SET `QuestDescription`='La Ligue des Explorateurs soupçonne la présence d’artéfacts dans la vallée d’Alterac, mais les Orcs Loup-de-givre nous empêchent de l’explorer. Nous ne pouvons pas laisser la Horde faire obstacle à la poursuite du savoir ! Abattez Drek’Thar, leur général. Sans lui, les Loups-de-Givre perdront leur mordant.$B$BDrek’Thar est au donjon Loup-de-givre, au sud de la vallée d''Alterac. Tuez-le et revenez me voir.', `VerifiedBuild`=25996 WHERE (`ID`=7141 AND `locale`='frFR');
